const now = new Date();
function hoursAgoISO(h){ return new Date(now.getTime() - Number(h) * 3600000).toISOString(); }

let rows = [];
if (CONFIG.mode === "LIVE") {
  rows = (CONFIG.live_requests || []).map(function(r){ return Object.assign({}, r, { data_label: "LIVE INPUT" }); });
} else {
  rows = DEMO.map(function(r){
    const o = Object.assign({}, r, { data_label: "SYNTHETIC DEMO DATA - NOT REAL PEOPLE" });
    o.submitted_at = hoursAgoISO(r.submitted_hours_ago);
    delete o.submitted_hours_ago;
    return o;
  });
}

if (!rows.length) {
  return [{ json: { halt: true, status: "REQUIRES_REVIEW", review_reasons: ["NO_INPUT_REQUESTS"],
    note: "No requests supplied. In LIVE mode add records to CONFIG.live_requests (node 2).",
    run_mode: CONFIG.mode, workflow_version: CONFIG.workflow_version, request_type: "NONE" } }];
}

return rows.map(function(r){
  return { json: Object.assign({ run_mode: CONFIG.mode, workflow_version: CONFIG.workflow_version,
    received_at: now.toISOString(), status: "OK", review_reasons: [] }, r) };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const EMAIL_RE = /^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}$/;
const VALID_TYPES = ["ONBOARDING","OFFBOARDING","IT_TICKET"];
const now = new Date();

function clean(s){ return String(s == null ? "" : s).replace(/\s+/g, " ").trim(); }
function titleCase(s){ return clean(s).toLowerCase().replace(/(^|[\s\-'])([a-z])/g, function(m, a, b){ return a + b.toUpperCase(); }); }
function addDaysISO(days){ return new Date(now.getTime() + Number(days) * 86400000).toISOString().slice(0, 10); }

return $input.all().map(function(item){
  const j = item.json;
  if (j.halt) return { json: j };
  const reasons = Array.isArray(j.review_reasons) ? j.review_reasons.slice() : [];

  const type = clean(j.request_type).toUpperCase();
  if (VALID_TYPES.indexOf(type) === -1) reasons.push("UNKNOWN_REQUEST_TYPE");

  const email = clean(j.requester_email).toLowerCase();
  const email_valid = EMAIL_RE.test(email);
  if (!email_valid) reasons.push("INVALID_REQUESTER_EMAIL");

  const rec = {
    request_id: clean(j.request_id) || "UNKNOWN",
    request_type: type,
    requester_name: titleCase(j.requester_name) || "UNKNOWN",
    requester_email: email,
    requester_email_valid: email_valid,
    submitted_at: j.submitted_at || j.received_at,
    data_label: j.data_label, run_mode: j.run_mode, workflow_version: j.workflow_version, received_at: j.received_at,
    status: "OK", review_reasons: reasons
  };

  if (type === "ONBOARDING") {
    rec.role = clean(j.role); rec.team = clean(j.team) || "UNKNOWN"; rec.manager_name = titleCase(j.manager_name) || "UNKNOWN";
    rec.work_mode = clean(j.work_mode).toLowerCase() || "unknown";
    const days = Number(j.start_date_days_from_now);
    rec.start_date_days_from_now = isNaN(days) ? null : days;
    rec.start_date = isNaN(days) ? "" : addDaysISO(days);
    if (!rec.role) reasons.push("MISSING_ROLE");
    if (isNaN(days)) reasons.push("MISSING_START_DATE");
  } else if (type === "OFFBOARDING") {
    rec.role = clean(j.role); rec.team = clean(j.team) || "UNKNOWN"; rec.manager_name = titleCase(j.manager_name) || "UNKNOWN";
    const days = Number(j.last_day_days_from_now);
    rec.last_day_days_from_now = isNaN(days) ? null : days;
    rec.last_day = isNaN(days) ? "" : addDaysISO(days);
    rec.tools_held = Array.isArray(j.tools_held) ? j.tools_held : [];
    if (!rec.role) reasons.push("MISSING_ROLE");
    if (isNaN(days)) reasons.push("MISSING_LAST_DAY");
    if (!rec.tools_held.length) reasons.push("NO_TOOLS_HELD_LISTED");
  } else if (type === "IT_TICKET") {
    rec.description = clean(j.description);
    if (!rec.description) reasons.push("MISSING_DESCRIPTION");
  }

  rec.review_reasons = reasons;
  rec.status = reasons.indexOf("UNKNOWN_REQUEST_TYPE") !== -1 ? "REQUIRES_REVIEW" : (reasons.length ? "REQUIRES_REVIEW" : "OK");
  return { json: rec };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const inv = {};
CONFIG.tool_inventory.forEach(function(t){ inv[t.tool] = { total: t.total_seats, used: t.used_seats, sensitive: t.sensitive, requires_manager_approval: t.requires_manager_approval }; });

function words(t, n){ const w = String(t||"").trim().split(/\s+/).filter(Boolean); return w.length<=n?w.join(" "):w.slice(0,n).join(" "); }

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  if (j.halt) return { json: j };
  const reasons = (j.review_reasons || []).slice();
  const roleCfg = CONFIG.roles[j.role];
  const usedGeneric = !roleCfg;
  const rc = roleCfg || CONFIG.generic_role;
  if (usedGeneric) reasons.push("ROLE_NOT_IN_TEMPLATE");

  const lines = rc.tools.map(function(tool){
    const t = inv[tool];
    if (!t) return { tool: tool, status: "UNKNOWN_TOOL_NOT_IN_INVENTORY" };
    let status;
    if (t.requires_manager_approval) status = "PENDING_MANAGER_APPROVAL";
    else if (t.used < t.total) { t.used += 1; status = "ASSIGNED"; }
    else status = "WAITLISTED";
    return { tool: tool, status: status, sensitive: t.sensitive };
  });

  const waitlisted = lines.filter(function(l){ return l.status === "WAITLISTED"; });
  const pending = lines.filter(function(l){ return l.status === "PENDING_MANAGER_APPROVAL"; });
  let day1_status = "READY";
  if (waitlisted.length) day1_status = "AT RISK - LICENSE SHORTAGE";
  else if (pending.length) day1_status = "AT RISK - AWAITING MANAGER APPROVAL";

  const urgent = (j.start_date_days_from_now !== null && j.start_date_days_from_now < 2 && day1_status !== "READY");
  if (urgent) reasons.push("URGENT_START_DATE_AT_RISK");

  const checklist = [
    { task: "Order hardware: " + rc.hardware, owner: "IT & Growth Support", due: j.start_date || "TBD" },
    { task: "Provision accounts: " + rc.tools.join(", "), owner: "IT & Growth Support", due: j.start_date || "TBD" },
    { task: "Send welcome message and first-day agenda", owner: j.manager_name || "Manager", due: j.start_date || "TBD" }
  ];
  if (pending.length) checklist.push({ task: "Get manager approval for: " + pending.map(function(p){ return p.tool; }).join(", "), owner: j.manager_name || "Manager", due: "Before start date" });
  if (waitlisted.length) checklist.push({ task: "Raise procurement request for additional seats: " + waitlisted.map(function(p){ return p.tool; }).join(", "), owner: "IT & Growth Support", due: "ASAP" });

  const draft = words("Hi " + (j.requester_name.split(" ")[0] || "there") + ", welcome to bookingkit! Your " + rc.hardware + " and core accounts (" + rc.tools.slice(0,3).join(", ") + (rc.tools.length>3?" and more":"") + ") are being set up ahead of your start date. See you on " + (j.start_date || "your start date") + "!", 70);

  j.function = rc.function;
  j.onboarding_detail = { role: j.role || "Unclassified", lines: lines, day1_status: day1_status, checklist: checklist, urgent: urgent,
    procurement_needed: waitlisted.map(function(l){ return l.tool; }), approvals_needed: pending.map(function(l){ return l.tool; }) };
  j.sla_text = "All core access ready 1 business day before start (" + (j.start_date || "TBD") + ")";
  j.sla_at_risk = urgent;
  j.integration = { slack_message: draft, google_workspace_payload: { primaryEmail: j.requester_email, name: j.requester_name, orgUnitPath: "/" + (j.team || "General"), tools: rc.tools }, jira_payload: null };
  j.draft_message = draft; j.draft_requires_approval = true;
  j.review_reasons = reasons; j.status = reasons.length ? "REQUIRES_REVIEW" : "OK";
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const inv = {};
CONFIG.tool_inventory.forEach(function(t){ inv[t.tool] = t; });
function words(t, n){ const w = String(t||"").trim().split(/\s+/).filter(Boolean); return w.length<=n?w.join(" "):w.slice(0,n).join(" "); }

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  if (j.halt) return { json: j };
  const reasons = (j.review_reasons || []).slice();

  const revoke_lines = (j.tools_held || []).map(function(tool){
    const t = inv[tool];
    return { tool: tool, sensitive: t ? t.sensitive : false, action: "REVOKE", known_inventory: Boolean(t) };
  });
  const sensitiveHeld = revoke_lines.filter(function(l){ return l.sensitive; });
  const security_risk = sensitiveHeld.length > 0 && j.last_day_days_from_now !== null && j.last_day_days_from_now <= 1;

  let status;
  if (security_risk) status = "IMMEDIATE ACTION REQUIRED";
  else if (j.last_day_days_from_now !== null && j.last_day_days_from_now < 2) status = "DUE SOON";
  else status = "SCHEDULED";

  const checklist = [
    { task: "Revoke access: " + (j.tools_held || []).join(", "), owner: "IT & Growth Support", due: j.last_day || "TBD" },
    { task: "Reclaim hardware", owner: "IT & Growth Support", due: j.last_day || "TBD" },
    { task: "Transfer document/repo ownership", owner: j.manager_name || "Manager", due: j.last_day || "TBD" }
  ];
  if (sensitiveHeld.length) checklist.unshift({ task: "PRIORITY: revoke sensitive access immediately: " + sensitiveHeld.map(function(l){ return l.tool; }).join(", "), owner: "IT & Growth Support", due: "Within 4 business hours of last day" });

  const draft = words("Hi " + (j.manager_name || "there") + ", " + j.requester_name + "'s last day is " + (j.last_day || "TBD") + ". Please confirm hardware return and any document ownership to reassign. IT will revoke system access on schedule" + (sensitiveHeld.length ? (", with " + sensitiveHeld.map(function(l){ return l.tool; }).join(", ") + " prioritised for immediate revocation.") : "."), 70);

  j.offboarding_detail = { role: j.role || "Unclassified", revoke_lines: revoke_lines, security_risk: security_risk, status: status, checklist: checklist };
  j.sla_text = sensitiveHeld.length ? "Sensitive access revoked within 4 business hours of last day; standard access within 1 business day" : "Standard access revoked within 1 business day of last day";
  j.sla_at_risk = security_risk;
  j.integration = { slack_message: draft, google_workspace_payload: null, jira_payload: null };
  j.draft_message = draft; j.draft_requires_approval = true;
  j.review_reasons = reasons; j.status = reasons.length ? "REQUIRES_REVIEW" : "OK";
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const CATS = CONFIG.ticket_categories;
const RANK = CONFIG.urgency_rank;
const EMAIL_RE = /[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}/gi;
const PHONE_RE = /\+?\d[\d\s\-()]{8,}\d/g;

function pickCategory(text){
  let best = "Other", bestHits = 0;
  Object.keys(CATS).forEach(function(c){
    if (c === "Other") return;
    const hits = CATS[c].keywords.filter(function(k){ return text.indexOf(k) !== -1; }).length;
    if (hits > bestHits) { bestHits = hits; best = c; }
  });
  return best;
}
function pickKB(text){
  let best = null, bestHits = 0;
  CONFIG.kb_articles.forEach(function(a){
    const hits = a.keywords.filter(function(k){ return text.indexOf(k) !== -1; }).length;
    if (hits > bestHits) { bestHits = hits; best = a; }
  });
  return best;
}

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  if (j.halt) return { json: j };
  const text = String(j.description || "").toLowerCase();
  const anonymised = text.replace(EMAIL_RE, "[EMAIL]").replace(PHONE_RE, "[PHONE]");

  const category = pickCategory(text);
  const catCfg = CATS[category];
  let urgency = catCfg.default_urgency;
  if (CONFIG.critical_keywords.some(function(k){ return text.indexOf(k) !== -1; })) urgency = "Critical";
  else if (CONFIG.urgency_bump_keywords.some(function(k){ return text.indexOf(k) !== -1; }) && RANK[urgency] < RANK["High"]) urgency = "High";

  const kb = pickKB(text);
  const sensitiveMentioned = CONFIG.tool_inventory.filter(function(t){ return t.requires_manager_approval && text.indexOf(t.tool.toLowerCase()) !== -1; });
  const sensitive_access_requested = category === "Account Request" && sensitiveMentioned.length > 0;
  const deflect_recommended = Boolean(kb) && category !== "Account Request" && !sensitive_access_requested;

  let sla_hours = catCfg.sla_hours;
  if (urgency === "Critical") sla_hours = Math.min(sla_hours, 2);

  const baseline = { category: category, urgency: urgency, kb_match: kb ? kb.title : null, kb_url: kb ? kb.url : null,
    deflect_recommended: deflect_recommended, sensitive_access_requested: sensitive_access_requested, sla_hours: sla_hours };

  j.ticket_baseline = baseline;
  j.ai_payload = {
    ticket_ref: j.request_id, anonymised_description: anonymised,
    kb_candidates: CONFIG.kb_articles.map(function(a){ return { title: a.title, category: a.category }; }),
    allowed_categories: Object.keys(CATS), allowed_urgencies: Object.keys(RANK), baseline: baseline
  };
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const base = $('10. Classify Ticket (Baseline)').all();
const incoming = $input.all();
const RANK = CONFIG.urgency_rank;
const CATS = Object.keys(CONFIG.ticket_categories);
const URG = Object.keys(RANK);
const KB_TITLES = CONFIG.kb_articles.map(function(a){ return a.title; });

function words(t, n){ const w = String(t||"").trim().split(/\s+/).filter(Boolean); return w.length<=n?w.join(" "):w.slice(0,n).join(" "); }
function scrub(t){
  let s = String(t || "");
  CONFIG.banned_ai_phrases.forEach(function(p){ s = s.replace(new RegExp(p.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "gi"), "[action not yet taken]"); });
  s = s.replace(/(\[action not yet taken\][\s,.!]*){2,}/gi, "[action not yet taken]. ");
  return s.replace(/\s{2,}/g, " ").replace(/\s+([,.!])/g, "$1").trim();
}

const out = [];
for (let i = 0; i < base.length; i++) {
  const j = JSON.parse(JSON.stringify(base[i].json));
  if (j.halt) { out.push({ json: j }); continue; }
  const reasons = (j.review_reasons || []).slice();
  const advisory = [];
  const b = j.ticket_baseline;
  let final = { category: b.category, urgency: b.urgency, recommended_action: "", suggested_kb_article: b.kb_match, clarifying_question: "", confidence: 0.55 };
  let source = "RULE_BASED_BASELINE";
  const resp = incoming[i] ? incoming[i].json : {};

  if (resp && resp.error) {
    reasons.push("AI_REQUEST_FAILED");
  } else if (resp && resp.choices && resp.choices[0] && resp.choices[0].message) {
    try {
      let raw = String(resp.choices[0].message.content || "").trim();
      raw = raw.replace(/^```json/i, "").replace(/^```/, "").replace(/```$/, "").trim();
      const p = JSON.parse(raw);
      const required = ["ticket_ref","category","urgency","recommended_action","suggested_kb_article","clarifying_question","confidence"];
      const missing = required.filter(function(k){ return p[k] === undefined; });
      if (missing.length) {
        reasons.push("AI_RESPONSE_MISSING_KEYS:" + missing.join(","));
      } else {
        if (CATS.indexOf(p.category) !== -1) final.category = p.category; else advisory.push("AI_CATEGORY_INVALID");
        if (URG.indexOf(p.urgency) !== -1) {
          final.urgency = RANK[p.urgency] >= RANK[b.urgency] ? p.urgency : b.urgency;
          if (RANK[p.urgency] < RANK[b.urgency]) advisory.push("AI_URGENCY_DOWNGRADE_BLOCKED");
        } else advisory.push("AI_URGENCY_INVALID");
        if (typeof p.recommended_action === "string" && p.recommended_action.length > 5) final.recommended_action = words(scrub(p.recommended_action), 60);
        if (p.suggested_kb_article === null || KB_TITLES.indexOf(p.suggested_kb_article) !== -1) final.suggested_kb_article = p.suggested_kb_article;
        else { final.suggested_kb_article = b.kb_match; advisory.push("AI_KB_SUGGESTION_NOT_IN_LIBRARY"); }
        if (typeof p.clarifying_question === "string" && p.clarifying_question.indexOf("?") !== -1) final.clarifying_question = words(scrub(p.clarifying_question), 30);
        if (typeof p.confidence === "number" && p.confidence >= 0 && p.confidence <= 1) final.confidence = Math.min(p.confidence, 0.75);
        source = advisory.length ? "LLM_FILTERED" : "LLM_VALIDATED";
      }
    } catch (e) {
      reasons.push("AI_RESPONSE_MALFORMED");
    }
  }

  if (!final.recommended_action) {
    final.recommended_action = b.deflect_recommended ? "Recommend pointing the requester to the matching self-serve article." : "Recommend a specialist review this ticket and act within the SLA window.";
  }

  j.ticket_final = final;
  j.analysis_source = source;
  j.advisory_flags = advisory;
  j.review_reasons = reasons;
  if (reasons.length) j.status = "REQUIRES_REVIEW";
  delete j.ai_payload;
  out.push({ json: j });
}
return out;

const CONFIG = $('2. Load CONFIG').first().json.config;
function words(t, n){ const w = String(t||"").trim().split(/\s+/).filter(Boolean); return w.length<=n?w.join(" "):w.slice(0,n).join(" "); }

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  if (j.halt) return { json: j };
  const b = j.ticket_baseline, f = j.ticket_final;
  const catCfg = CONFIG.ticket_categories[f.category] || CONFIG.ticket_categories["Other"];
  let sla_hours = catCfg.sla_hours;
  if (f.urgency === "Critical") sla_hours = Math.min(sla_hours, 2);

  const deflect = b.deflect_recommended && !b.sensitive_access_requested;
  const owner = b.sensitive_access_requested ? "IT & Growth Support + Manager approval" : "AI & IT Ops Specialist";

  const hoursWaiting = j.submitted_at ? (Date.now() - new Date(j.submitted_at).getTime()) / 3600000 : 0;
  const sla_at_risk = hoursWaiting > sla_hours;

  const kbArticle = f.suggested_kb_article ? CONFIG.kb_articles.filter(function(a){ return a.title === f.suggested_kb_article; })[0] : null;
  let draft;
  if (deflect && kbArticle) {
    draft = words("Hi " + j.requester_name.split(" ")[0] + ", thanks for reaching out. This looks like something you can fix yourself: " + kbArticle.title + " - " + kbArticle.url + ". Reply here if that does not solve it and I will pick it up directly.", 60);
  } else {
    draft = words("Hi " + j.requester_name.split(" ")[0] + ", thanks for the report. " + f.recommended_action + (b.sensitive_access_requested ? " This needs manager sign-off first, which I have requested." : (" Expect an update within " + sla_hours + " hours.")), 60);
  }

  j.ticket_detail = { category: f.category, urgency: f.urgency, kb_match: f.suggested_kb_article, kb_url: kbArticle ? kbArticle.url : null,
    deflected: deflect, sensitive_access_requested: b.sensitive_access_requested, recommended_action: f.recommended_action,
    clarifying_question: f.clarifying_question, owner: owner, sla_hours: sla_hours };
  j.sla_text = "Target: " + sla_hours + " business hour(s)";
  j.sla_at_risk = sla_at_risk;
  j.hours_since_submission = Math.round(hoursWaiting * 10) / 10;
  j.integration = { slack_message: draft, google_workspace_payload: null,
    jira_payload: deflect ? null : { summary: f.category + ": " + j.requester_name, description: j.description, priority: f.urgency, dueInHours: sla_hours, requiresManagerApproval: b.sensitive_access_requested } };
  j.draft_message = draft; j.draft_requires_approval = true;
  return { json: j };
});

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  if (j.halt) return { json: j };
  j.review_reasons = (j.review_reasons || []).concat(["UNKNOWN_REQUEST_TYPE"]);
  j.status = "REQUIRES_REVIEW";
  j.sla_text = "N/A"; j.sla_at_risk = false;
  j.integration = { slack_message: null, google_workspace_payload: null, jira_payload: null };
  j.draft_message = ""; j.draft_requires_approval = false;
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const rows = (($input.first().json.requests) || []).filter(function(r){ return !r.halt; });

function esc(s){ return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); }
function tally(list){ const o = {}; list.forEach(function(k){ o[k] = (o[k] || 0) + 1; }); return o; }

const onboarding = rows.filter(function(r){ return r.request_type === "ONBOARDING"; });
const offboarding = rows.filter(function(r){ return r.request_type === "OFFBOARDING"; });
const tickets = rows.filter(function(r){ return r.request_type === "IT_TICKET"; });
const unmatched = rows.filter(function(r){ return r.request_type !== "ONBOARDING" && r.request_type !== "OFFBOARDING" && r.request_type !== "IT_TICKET"; });

// --- License inventory reconciliation ---
const inv = {};
CONFIG.tool_inventory.forEach(function(t){ inv[t.tool] = { total: t.total_seats, previously_used: t.used_seats, released: 0, assigned: 0, sensitive: t.sensitive }; });
offboarding.forEach(function(o){ (o.offboarding_detail ? o.offboarding_detail.revoke_lines : []).forEach(function(l){ if (inv[l.tool]) inv[l.tool].released += 1; }); });
onboarding.forEach(function(o){ (o.onboarding_detail ? o.onboarding_detail.lines : []).filter(function(l){ return l.status === "ASSIGNED"; }).forEach(function(l){ if (inv[l.tool]) inv[l.tool].assigned += 1; }); });
const inventory_table = Object.keys(inv).map(function(tool){
  const t = inv[tool];
  const current = Math.max(0, Math.min(t.total, t.previously_used - t.released + t.assigned));
  const remaining = t.total - current;
  return { tool: tool, total: t.total, previously_used: t.previously_used, released_this_run: t.released, assigned_this_run: t.assigned,
    currently_used: current, remaining: remaining, utilization_pct: Math.round((current / t.total) * 1000) / 10,
    near_capacity: remaining <= 1, sensitive: t.sensitive };
}).sort(function(a, b){ return b.utilization_pct - a.utilization_pct; });

// --- Automation opportunity detection ---
const catCounts = tally(tickets.map(function(t){ return t.ticket_detail ? t.ticket_detail.category : "Other"; }));
const opportunities = Object.keys(catCounts).filter(function(c){ return catCounts[c] >= CONFIG.automation_opportunity_threshold; }).map(function(c){
  const sug = CONFIG.automation_suggestions[c] || CONFIG.automation_suggestions["Other"];
  return { category: c, count: catCounts[c], suggested_tool: sug.tool_suggestion, description: sug.description };
}).sort(function(a, b){ return b.count - a.count; });

// --- AI enablement ---
const enablement = CONFIG.ai_enablement.map(function(e){ return Object.assign({}, e, { clinic_recommended: e.adoption_pct < CONFIG.ai_enablement_threshold_pct }); });

// --- Ticket queue ---
const RANK = CONFIG.urgency_rank;
const ticketQueue = tickets.slice().sort(function(a, b){
  const ur = (RANK[b.ticket_detail.urgency] || 0) - (RANK[a.ticket_detail.urgency] || 0);
  if (ur !== 0) return ur;
  return (b.sla_at_risk ? 1 : 0) - (a.sla_at_risk ? 1 : 0);
});
const deflected = tickets.filter(function(t){ return t.ticket_detail && t.ticket_detail.deflected; });

// --- Review queue ---
const reviewQueue = rows.filter(function(r){ return r.status === "REQUIRES_REVIEW"; });
const reasonTally = tally([].concat.apply([], rows.map(function(r){ return (r.review_reasons || []).map(function(x){ return x.split(":")[0]; }); })));

const mins = CONFIG.assumptions;
const estHours = Math.round((onboarding.length * mins.onboarding_minutes_saved_per_hire + tickets.length * mins.ticket_triage_minutes_saved_per_ticket) / 60 * 10) / 10;

const dashboard = {
  report: "bookingkit IT Ops & AI Agent Copilot - Ops Dashboard", company: CONFIG.company, run_mode: CONFIG.mode, workflow_version: CONFIG.workflow_version,
  generated_at: new Date().toISOString(), data_label: rows.length ? rows[0].data_label : "NO DATA",
  requests_processed: rows.length, onboarding_count: onboarding.length, offboarding_count: offboarding.length, ticket_count: tickets.length, unmatched_count: unmatched.length,
  onboarding_ready: onboarding.filter(function(o){ return o.onboarding_detail.day1_status === "READY"; }).length,
  onboarding_at_risk: onboarding.filter(function(o){ return o.onboarding_detail.day1_status !== "READY"; }).length,
  offboarding_immediate_action: offboarding.filter(function(o){ return o.offboarding_detail.security_risk; }).length,
  tickets_deflected: deflected.length, tickets_deflection_rate_pct: tickets.length ? Math.round((deflected.length / tickets.length) * 1000) / 10 : 0,
  tickets_sla_at_risk: tickets.filter(function(t){ return t.sla_at_risk; }).length,
  requires_review: reviewQueue.length,
  automation_opportunities: opportunities, ai_enablement: enablement, inventory_table: inventory_table,
  estimated_hours_saved_this_run: estHours, estimate_note: mins.label + " (" + mins.onboarding_minutes_saved_per_hire + " min/hire, " + mins.ticket_triage_minutes_saved_per_ticket + " min/ticket assumed).",
  data_quality_issues: reasonTally,
  measurement_note: "Measures throughput, deflection and risk. It does not measure IT budget savings and is not a claim of actual hours saved without validated baseline figures.",
  policy_note: CONFIG.data_use_policy.principles
};

function badge(cls, t){ return '<span class="b ' + cls + '">' + esc(t) + "</span>"; }
function kpi(v, l){ return '<div class="k"><b>' + esc(v) + "</b><span>" + esc(l) + "</span></div>"; }
const css = "body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;margin:0;background:#f5f6f8;color:#1b1f24}.wrap{max-width:1220px;margin:0 auto;padding:24px}h1{font-size:22px;margin:0}.sub{color:#5a6472;font-size:13px}.banner{background:#e7f0ff;border:1px solid #b9d3fb;padding:8px 12px;border-radius:8px;font-size:12px;margin:12px 0}.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:14px 0}.k{background:#fff;border:1px solid #e3e6eb;border-radius:10px;padding:10px 12px}.k b{display:block;font-size:22px}.k span{font-size:11px;color:#5a6472;text-transform:uppercase;letter-spacing:.04em}table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #e3e6eb;font-size:12.5px}th,td{word-break:break-word;padding:7px 9px;border-bottom:1px solid #eef0f3;text-align:left;vertical-align:top}th{background:#fafbfc;font-size:11px;text-transform:uppercase;color:#5a6472}.b{display:inline-block;padding:1px 8px;border-radius:10px;font-weight:600;font-size:11px;color:#fff}.bhigh{background:#b42318}.bmed{background:#b7791f}.blow{background:#1a7f4b}.bready{background:#1a7f4b}.brisk{background:#b42318}.warn{color:#b42318;font-weight:600}.ok{color:#1a7f4b;font-weight:600}h2{font-size:15px;margin:22px 0 8px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}@media(max-width:800px){.grid2{grid-template-columns:1fr}}.tw{overflow-x:auto}.small{font-size:11.5px;color:#5a6472}";

const h = [];
h.push('<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IT Ops Copilot</title><style>' + css + "</style></head><body><div class=\"wrap\">");
h.push("<h1>bookingkit IT Ops &amp; AI Agent Copilot</h1>");
h.push('<div class="sub">' + esc(CONFIG.company) + " | mode " + esc(CONFIG.mode) + " | v" + esc(CONFIG.workflow_version) + " | " + esc(dashboard.generated_at) + "</div>");
h.push('<div class="banner"><b>' + esc(dashboard.data_label) + ".</b> All requesters, tickets and license figures shown are synthetic. The AI agent classifies and drafts only; it never claims to have granted access or resolved a ticket, and nothing is sent without push_enabled and human approval.</div>");
h.push('<div class="kpis">' + kpi(rows.length, "Requests processed") + kpi(dashboard.onboarding_ready + "/" + onboarding.length, "New hires day-1 ready") + kpi(dashboard.offboarding_immediate_action, "Leavers needing urgent revoke") + kpi(dashboard.tickets_deflection_rate_pct + "%", "Tickets self-serve deflected") + kpi(dashboard.tickets_sla_at_risk, "Tickets at SLA risk") + kpi(opportunities.length, "Automation opportunities found") + kpi(dashboard.requires_review, "Requires review") + kpi(estHours + " h", "Est. time saved (this run)*") + "</div>");
h.push('<div class="small">*' + esc(dashboard.estimate_note) + "</div>");

h.push("<h2>Onboarding - new hire readiness</h2><div class=\"tw\"><table><tr><th>Hire</th><th>Role</th><th>Start</th><th>Status</th><th>Tools</th><th>Checklist owner(s)</th></tr>");
onboarding.forEach(function(o){
  const d = o.onboarding_detail;
  h.push("<tr><td><b>" + esc(o.requester_name) + "</b><br><span class=\"small\">" + esc(o.team) + "</span></td><td>" + esc(d.role) + "</td><td>" + esc(o.start_date) + (o.sla_at_risk ? '<br><span class="warn">URGENT</span>' : "") + "</td><td>" + (d.day1_status === "READY" ? badge("bready", "READY") : badge("brisk", d.day1_status)) + "</td><td>" + d.lines.map(function(l){ return esc(l.tool) + " (" + esc(l.status.replace("_"," ")) + ")"; }).join("<br>") + "</td><td>" + d.checklist.map(function(c){ return esc(c.owner); }).filter(function(v,i,a){return a.indexOf(v)===i;}).join(", ") + "</td></tr>");
});
h.push("</table></div>");

h.push("<h2>Offboarding - access &amp; asset recovery</h2><div class=\"tw\"><table><tr><th>Leaver</th><th>Role</th><th>Last day</th><th>Status</th><th>Access to revoke</th></tr>");
offboarding.forEach(function(o){
  const d = o.offboarding_detail;
  h.push("<tr><td><b>" + esc(o.requester_name) + "</b><br><span class=\"small\">" + esc(o.team) + "</span></td><td>" + esc(d.role) + "</td><td>" + esc(o.last_day) + "</td><td>" + (d.security_risk ? badge("brisk", d.status) : badge("bready", d.status)) + "</td><td>" + d.revoke_lines.map(function(l){ return esc(l.tool) + (l.sensitive ? " (sensitive)" : ""); }).join(", ") + "</td></tr>");
});
h.push("</table></div>");

h.push("<h2>IT ticket queue (highest priority first)</h2><div class=\"tw\"><table><tr><th>Requester</th><th>Category</th><th>Urgency</th><th>Deflected</th><th>Owner</th><th>SLA</th><th>Draft</th><th>Status</th></tr>");
ticketQueue.forEach(function(t){
  const d = t.ticket_detail;
  const ub = d.urgency === "Critical" || d.urgency === "High" ? "bhigh" : (d.urgency === "Medium" ? "bmed" : "blow");
  h.push("<tr><td>" + esc(t.requester_name) + "<br><span class=\"small\">" + esc((t.description||"").slice(0,60)) + "...</span></td><td>" + esc(d.category) + "</td><td>" + badge(ub, d.urgency) + "</td><td>" + (d.deflected ? '<span class="ok">Yes - KB</span>' : "No") + "</td><td>" + esc(d.owner) + "</td><td>" + esc(t.sla_text) + (t.sla_at_risk ? '<br><span class="warn">AT RISK</span>' : "") + "</td><td class=\"small\">" + esc(t.draft_message) + "</td><td>" + (t.status === "OK" ? '<span class="ok">OK</span>' : '<span class="warn">REVIEW</span>') + "</td></tr>");
});
h.push("</table></div>");

h.push('<div class="grid2"><div><h2>Automation opportunities (recurring ticket categories)</h2><table><tr><th>Category</th><th>Count</th><th>Suggested build</th></tr>');
if (!opportunities.length) h.push('<tr><td colspan="3">None yet at this volume.</td></tr>');
opportunities.forEach(function(o){ h.push("<tr><td>" + esc(o.category) + "</td><td><b>" + o.count + "</b></td><td><b>" + esc(o.suggested_tool) + "</b><br><span class=\"small\">" + esc(o.description) + "</span></td></tr>"); });
h.push("</table></div><div><h2>AI enablement - adoption by team (simulated)</h2><table><tr><th>Team</th><th>Adoption</th><th>Clinic?</th></tr>");
enablement.sort(function(a,b){return a.adoption_pct-b.adoption_pct;}).forEach(function(e){ h.push("<tr><td>" + esc(e.team) + "</td><td>" + e.adoption_pct + "%</td><td>" + (e.clinic_recommended ? '<span class="warn">Recommend clinic</span>' : '<span class="ok">On track</span>') + "</td></tr>"); });
h.push("</table></div></div>");

