inventory_table.forEach(function(t){ h.push("<tr><td>" + esc(t.tool) + (t.sensitive ? ' <span class="small">(sensitive)</span>' : "") + "</td><td>" + t.currently_used + " / " + t.total + "</td><td>" + t.utilization_pct + "%</td><td>" + t.released_this_run + "</td><td>" + t.assigned_this_run + "</td><td>" + (t.near_capacity ? '<span class="warn">NEAR CAPACITY</span>' : '<span class="ok">OK</span>') + "</td></tr>"); });
h.push("</table></div>");

h.push('<div class="grid2"><div><h2>Review queue</h2><table><tr><th>Request</th><th>Type</th><th>Reasons</th></tr>');
if (!reviewQueue.length) h.push('<tr><td colspan="3">None</td></tr>');
reviewQueue.forEach(function(r){ h.push("<tr><td>" + esc(r.requester_name) + "</td><td>" + esc(r.request_type) + "</td><td>" + esc((r.review_reasons||[]).join(", ")) + "</td></tr>"); });
h.push("</table></div><div><h2>Data quality issues (tally)</h2><table><tr><th>Issue</th><th>Count</th></tr>");
Object.keys(reasonTally).forEach(function(k){ h.push("<tr><td>" + esc(k) + "</td><td>" + reasonTally[k] + "</td></tr>"); });
h.push("</table></div></div>");
h.push('<div class="small" style="margin-top:22px">' + esc(dashboard.measurement_note) + "</div></div></body></html>");

return [{ json: { dashboard: dashboard, ticket_queue: ticketQueue.map(function(t){ return { requester: t.requester_name, category: t.ticket_detail.category, urgency: t.ticket_detail.urgency, deflected: t.ticket_detail.deflected, sla_at_risk: t.sla_at_risk }; }),
  inventory_table: inventory_table, automation_opportunities: opportunities, html_report: h.join("") } }];
